def rotate_refresh_token(session):
    revoke_active_device_links(session.client)
    return issue_grant(session)


def revoke_active_device_links(client):
    mark_client_links_stale(client)


def issue_grant(session):
    return mint_token(session.subject)

class SessionSweeper:
    def purge_stale_grant_rows(self, cutoff):
        self.store.delete_before(cutoff)

    def audit_sweep(self):
        self.purge_stale_grant_rows(self.watermark())
